typedef struct {float x,y,a; int ride,pending,anim,action,jump; bool armed,firelock; float nx[6],ny[6]; bool alive[6]; unsigned phase; bool chord; float vx[8],vy[8]; float depth[128]; bool keys[6],car,quit; unsigned cash,mission; FuriMessageQueue* q; FuriMutex* lock;} Game;
static bool wall(float x,float y){int a=(int)x,b=(int)y;return x<0||y<0||a>=N||b>=N||(map[b][a]=='#'||map[b][a]=='H'||map[b][a]=='V');}
static void vehicle(Canvas* c,int x,int y,int w,int h,bool bike){
if(w<4||h<4)return;
if(bike){int r=h/5;if(r<1)r=1;canvas_draw_disc(c,x+w/4,y+h-r,r);canvas_draw_disc(c,x+3*w/4,y+h-r,r);canvas_draw_line(c,x+w/4,y+h-r,x+w/2,y+h/3);canvas_draw_line(c,x+w/2,y+h/3,x+3*w/4,y+h-r);canvas_draw_line(c,x+w/4,y+h-r,x+3*w/4,y+h-r);canvas_draw_line(c,x+w/2,y+h/3,x+w*3/4,y);canvas_draw_line(c,x+w*3/4,y,x+w-1,y);canvas_draw_box(c,x+w/4,y+h/3,w/3+1,2);return;}
canvas_set_color(c,ColorWhite);canvas_draw_box(c,x+1,y+h/3,w-2,h-h/3);canvas_set_color(c,ColorBlack);
int l=x+w/5,r=x+w-1-w/5,t=y+1,m=y+h/2;
canvas_draw_line(c,l,t,r,t);canvas_draw_line(c,l,t,x+1,m);canvas_draw_line(c,r,t,x+w-2,m);canvas_draw_line(c,x+1,m,x+w-2,m);
for(int j=t+1;j<m;j++){int inset=(m-j)*(w/5)/(m-t);canvas_draw_line(c,x+2+inset,j,x+w-3-inset,j);}
canvas_draw_rbox(c,x,y+h/2,w,h-h/2,2);
canvas_set_color(c,ColorWhite);canvas_draw_box(c,x+2,y+h*2/3,w/5,2);canvas_draw_box(c,x+w-2-w/5,y+h*2/3,w/5,2);canvas_draw_line(c,x+w/3,y+h-2,x+w*2/3,y+h-2);canvas_set_color(c,ColorBlack);canvas_draw_box(c,x+1,y+h-2,2,2);canvas_draw_box(c,x+w-3,y+h-2,2,2);
}
static void hero(Canvas* c,unsigned phase,int action,int anim,bool armed){
static const char* sprite[]={".....######.....","....########....","....########....","....########....",".....#....#.....",".....#....#.....","...###....###...","..##.#....#.##..",".##..#....#..##.",".#...#....#...#.",".#...#....#...#.",".#...#....#...#.",".#...#....#...#.",".#...#....#...#.",".#...#....#...#.",".#...######...#.","..#..######..#..","....########....","....###..###....","....###..###...."};
int x=56+(action==1||action==2?(8-anim)*2:0),y=39-(phase%6==3);for(int j=0;j<20;j++)for(int i=0;i<16;i++){if(sprite[j][i]=='#')canvas_draw_dot(c,x+i,y+j);else if(i>=5&&i<=10&&j>=4&&j<=16){canvas_set_color(c,ColorWhite);canvas_draw_dot(c,x+i,y+j);canvas_set_color(c,ColorBlack);}}
int step=(phase/3)%2?2:-2;canvas_draw_line(c,x+5,y+19,x+5+step,62);canvas_draw_line(c,x+10,y+19,x+10-step,62);if(armed||action==3){canvas_draw_line(c,x+13,y+10,x+17,y+6+anim/3);canvas_draw_box(c,x+16,y+5+anim/3,5,2);}if(action==4)canvas_draw_line(c,x+22,y+5,x+24,y+3);}
static void palm(Canvas* c,int x,int y,int h){if(h<5)return;int t=y-h;canvas_draw_line(c,x,y,x-2,t);canvas_draw_line(c,x+1,y,x-1,t);for(int i=-2;i<=2;i++){int ex=x+i*h/4;canvas_draw_line(c,x-2,t,ex,t-2);canvas_draw_line(c,ex,t-2,ex+i,t+3);}}
static void draw(Canvas* c,void* ctx){Game* g=ctx;furi_mutex_acquire(g->lock,FuriWaitForever);canvas_clear(c);for(int i=0;i<3;i++){int x=(i*40+12+(int)(g->a*8))%100;if(x<0)x+=100;canvas_draw_line(c,x,25,x+12,12+i*3);canvas_draw_line(c,x+12,12+i*3,x+25,25);}float dx=cosf(g->a),dy=sinf(g->a);float cx=g->x,cy=g->y;for(float d=.1f;d<.9f;d+=.1f){if(wall(g->x-d*dx,g->y-d*dy))break;cx=g->x-d*dx;cy=g->y-d*dy;}
/* Ground-plane perspective: world-aligned road and sidewalk texture. */
for(int y=29;y<64;y++){float d=52.f/(y-27);for(int x=0;x<128;x+=2){float side=(x-64)*d/55.f;float wx=cx+dx*d-dy*side,wy=cy+dy*d+dx*side;if(wx<0||wy<0||wx>=N||wy>=N)continue;float fx=wx-floorf(wx),fy=wy-floorf(wy);int ix=(int)wx,iy=(int)wy;bool road=iy%5==0||iy%5==1||ix%6==0||ix%6==1;bool curb=(fx<.09f||fy<.09f);if((!road&&((x+y)&2))||curb||(road&&((iy%5==1&&fy<.10f&&ix%2==0)||(ix%6==1&&fx<.10f&&iy%2==0))))canvas_draw_dot(c,x,y);}}
/* Solid variable-height facades, with world-space window patterns. */
for(int x=0;x<128;x++){float off=(x-64)/55.f,rx=dx-dy*off,ry=dy+dx*off,d=.08f;while(d<15&&!wall(cx+rx*d,cy+ry*d))d+=.055f;g->depth[x]=d;if(d>=15)continue;float wx=cx+rx*d,wy=cy+ry*d;int ix=(int)wx,iy=(int)wy;if(ix<0||iy<0||ix>=N||iy>=N)continue;float h=map[iy][ix]=='H'?3.5f+((ix+iy)%4)*.45f:map[iy][ix]=='V'?1.5f:1.15f+((ix/3+iy/2)%3)*.55f;int top=27+(int)((.95f-h)*55/d),bottom=27+(int)(.95f*55/d);int lo=top<0?0:top,hi=bottom>63?63:bottom;float u=fabsf(rx)>fabsf(ry)?wy:wx;for(int y=lo;y<=hi;y++){float v=.95f-(y-27)*d/55.f;bool window=((int)(u*5)&3)<2&&((int)(v*6)&3)<2;bool trim=((int)(v*12)%6)==0;bool ink=window||trim||((ix+iy)%2&&((x+y)&1));canvas_set_color(c,ink?ColorBlack:ColorWhite);canvas_draw_dot(c,x,y);}canvas_set_color(c,ColorBlack);if(top>=0&&top<64)canvas_draw_dot(c,x,top);}
for(int i=0;i<5;i++){int y=30+i*i;canvas_draw_line(c,63-i/2,y,64+i/2,y);}for(int i=0;i<10;i++){float ax=1.5f+i*2-cx,ay=4.5f-cy,z=ax*dx+ay*dy;if(z<.6f)continue;int sx=64+(int)((-ax*dy+ay*dx)*55/z);if(sx<8||sx>119||z>g->depth[sx])continue;int h=(int)(27/z);if(h>28)h=28;int y=27+(int)(52/z);if(y>53)y=53;palm(c,sx,y,h);}
for(int i=0;i<8;i++){if(i==g->ride)continue;float ax=g->vx[i]-cx,ay=g->vy[i]-cy,z=ax*dx+ay*dy,side=-ax*dy+ay*dx;if(z<.2f)continue;int sx=64+(int)(side*55/z);if(sx<4||sx>123||z>g->depth[sx])continue;int w=(int)((i%3==2?9:18)/z),h=(int)(12/z);if(w>28)w=28;if(h>18)h=18;int bottom=27+(int)(52/z);if(bottom>53)bottom=53;if(sx-w/2<0||sx+w/2>127)continue;vehicle(c,sx-w/2,bottom-h,w,h,i%3==2);}
for(int i=0;i<6;i++){if(!g->alive[i])continue;float ax=g->nx[i]-cx,ay=g->ny[i]-cy,z=ax*dx+ay*dy;if(z<.3f)continue;int sx=64+(int)((-ax*dy+ay*dx)*55/z);if(sx<5||sx>122||z>g->depth[sx])continue;int h=(int)(18/z);if(h>22)h=22;if(h<4)continue;int y=27+(int)(52/z);if(y>53)y=53;canvas_draw_disc(c,sx,y-h,h/6);canvas_draw_line(c,sx,y-h+2,sx,y-h/3);canvas_draw_line(c,sx-2,y-h/2,sx+2,y-h/2);canvas_draw_line(c,sx,y-h/3,sx-2,y);canvas_draw_line(c,sx,y-h/3,sx+2,y);}
for(int i=0;i<2;i++){float ax=(i?28.5f:13.5f)-cx,ay=30.5f-cy,z=ax*dx+ay*dy;if(z<.4f)continue;int sx=64+(int)((-ax*dy+ay*dx)*55/z);if(sx<8||sx>119||z>g->depth[sx])continue;int y=27+(int)(52/z);if(y>53)y=53;canvas_draw_line(c,sx-7,y,sx+7,y-6);canvas_draw_line(c,sx+7,y-6,sx+7,y);canvas_draw_line(c,sx-7,y,sx+7,y);}
if(g->ride>=0){vehicle(c,53,36-g->jump,22,17,g->ride%3==2);if(g->ride%3==2)canvas_draw_disc(c,64,34-g->jump,3);}else hero(c,g->phase,g->action,g->anim,g->armed);
canvas_set_font(c,FontSecondary);char s[32];canvas_set_color(c,ColorWhite);canvas_draw_box(c,79,0,49,17);canvas_set_color(c,ColorBlack);snprintf(s,sizeof(s),"$%u",g->cash);canvas_draw_str(c,80,8,s);canvas_draw_str(c,80,16,g->armed?"HP100 G":"HP100");canvas_set_color(c,ColorWhite);canvas_draw_disc(c,13,50,12);canvas_set_color(c,ColorBlack);canvas_draw_circle(c,13,50,12);for(int yy=-9;yy<=9;yy++)for(int xx=-9;xx<=9;xx++){if(xx*xx+yy*yy>90)continue;int mx=(int)g->x+xx/2,my=(int)g->y+yy/2;if(mx>=0&&my>=0&&mx<N&&my<N&&map[my][mx]=='#')canvas_draw_dot(c,13+xx,50+yy);}canvas_draw_line(c,13,47,11,52);canvas_draw_line(c,13,47,15,52);canvas_draw_line(c,11,52,15,52);canvas_set_color(c,ColorWhite);canvas_draw_box(c,0,0,29,9);canvas_set_color(c,ColorBlack);canvas_draw_str(c,1,8,"VC 0.7");if(g->x>28&&g->x<37&&g->y<11){canvas_set_color(c,ColorWhite);canvas_draw_box(c,39,0,38,9);canvas_set_color(c,ColorBlack);canvas_draw_str(c,40,8,"HOME");}else if(g->y>29){canvas_set_color(c,ColorWhite);canvas_draw_box(c,39,0,38,9);canvas_set_color(c,ColorBlack);canvas_draw_str(c,40,8,"HILLS");}furi_mutex_release(g->lock);}
static void input(InputEvent* e,void* ctx){Game* g=ctx;furi_message_queue_put(g->q,e,0);}
int32_t gta_main(void* p){UNUSED(p);Game* g=calloc(1,sizeof(Game));if(!g)return -1;g->x=4.5f;g->y=5.5f;g->ride=-1;g->pending=-1;for(int i=0;i<6;i++){g->nx[i]=2.5f+i*3;g->ny[i]=9.5f;g->alive[i]=true;}float vx[8]={3.5,7.5,12.5,32.5,29.5,13.5,28.5,11.5},vy[8]={1.5,4.5,5.5,8.5,9.5,14.5,29.5,1.5};for(int i=0;i<8;i++){g->vx[i]=vx[i];g->vy[i]=vy[i];}g->q=furi_message_queue_alloc(16,sizeof(InputEvent));g->lock=furi_mutex_alloc(FuriMutexTypeNormal);ViewPort* v=view_port_alloc();view_port_draw_callback_set(v,draw,g);view_port_input_callback_set(v,input,g);Gui* gui=furi_record_open(RECORD_GUI);gui_add_view_port(gui,v,GuiLayerFullscreen);while(!g->quit){InputEvent e;bool got=furi_message_queue_get(g->q,&e,30)==FuriStatusOk;furi_mutex_acquire(g->lock,FuriWaitForever);if(got){if(e.key==InputKeyBack&&e.type==InputTypeShort)g->quit=true;if(e.key<6){if(e.type==InputTypePress)g->keys[e.key]=true;if(e.type==InputTypeRelease)g->keys[e.key]=false;}}bool combo=g->keys[InputKeyDown]&&g->keys[InputKeyOk];if(combo&&!g->chord&&!g->anim){if(g->ride>=0){g->ride=-1;float ex=g->x-sinf(g->a)*.65f,ey=g->y+cosf(g->a)*.65f;if(!wall(ex,ey)){g->x=ex;g->y=ey;}}else{float best=1.44f;int near=-1;for(int i=0;i<8;i++){float ax=g->x-g->vx[i],ay=g->y-g->vy[i],d=ax*ax+ay*ay;if(d<best){best=d;near=i;}}if(near>=0){g->pending=near;g->action=near%3==2?2:1;g->anim=8;}}}g->chord=combo;bool gun=g->keys[InputKeyLeft]&&g->keys[InputKeyOk];bool shot=g->keys[InputKeyRight]&&g->keys[InputKeyOk];if((gun||shot)&&!g->firelock&&g->ride<0&&!g->anim){if(gun){g->armed=!g->armed;g->action=3;g->anim=8;}else if(g->armed){g->action=4;g->anim=4;for(int i=0;i<6;i++){float ax=g->nx[i]-g->x,ay=g->ny[i]-g->y,d=ax*cosf(g->a)+ay*sinf(g->a),side=-ax*sinf(g->a)+ay*cosf(g->a);if(g->alive[i]&&d>0&&d<5&&fabsf(side)<.4f){bool clear=true;for(float t=.1f;t<d;t+=.1f)if(wall(g->x+cosf(g->a)*t,g->y+sinf(g->a)*t))clear=false;if(clear){g->alive[i]=false;break;}}}}}g->firelock=gun||shot;if(g->anim&&!--g->anim){if(g->pending>=0){g->ride=g->pending;g->pending=-1;g->x=g->vx[g->ride];g->y=g->vy[g->ride];}g->action=0;}if(g->keys[InputKeyLeft]&&!gun)g->a-=.09f;if(g->keys[InputKeyRight]&&!shot)g->a+=.09f;float speed=(g->ride>=0?(g->ride%3==2?.20f:.15f):g->keys[InputKeyOk]?.11f:.07f)*(g->keys[InputKeyUp]-(g->keys[InputKeyDown]&&!combo));if(g->anim)speed=0;if(g->jump>0)g->jump--;if(g->ride>=0&&speed>0&&map[(int)g->y][(int)g->x]=='R'&&!g->jump)g->jump=10;for(int i=0;i<6;i++){float nx=g->nx[i]+.025f*cosf(g->phase*.03f+i);if(!wall(nx,g->ny[i]))g->nx[i]=nx;}float x=g->x+cosf(g->a)*speed,y=g->y+sinf(g->a)*speed;if(!wall(x,g->y))g->x=x;if(!wall(g->x,y))g->y=y;if(speed!=0)g->phase++;else g->phase=0;if(g->ride>=0){g->vx[g->ride]=g->x;g->vy[g->ride]=g->y;}float target=g->mission%2?1.5f:27.5f;if(fabsf(g->x-target)<.6f&&fabsf(g->y-target)<.6f){g->cash+=250;g->mission++;}furi_mutex_release(g->lock);view_port_update(v);}gui_remove_view_port(gui,v);view_port_free(v);furi_record_close(RECORD_GUI);furi_message_queue_free(g->q);furi_mutex_free(g->lock);free(g);return 0;}